class Solution {
    public int deleteAndEarn(int[] nums){
        int maximum=0;
        for(int value:nums)maximum=Math.max(maximum,value);
        int[] points=new int[maximum+1];
        for(int value:nums)points[value]+=value;
        int take=0,skip=0;
        for(int value=0;value<=maximum;value++){
            int newTake=skip+points[value],newSkip=Math.max(skip,take);
            take=newTake;
            skip=newSkip;
        }
        return Math.max(take,skip);
    }
}

code.kotlin:
class Solution {
    fun deleteAndEarn(nums:IntArray):Int{
        val points=IntArray((nums.maxOrNull()?:0)+1);
        for(value in nums)points[value]+=value;
        var take=0;
        var skip=0;
        for(score in points){
            val newTake=skip+score;
            val newSkip=maxOf(skip,take);
            take=newTake;
            skip=newSkip
        };
        return maxOf(take,skip)
    }
}

